impl Solution {
    pub fn longest_mountain(arr: Vec<i32>) -> i32 {
        let n = arr.len();
        if n < 3 {
            return 0;
        }
        let mut max_len = 0usize;
        let mut i = 1usize;
        while i + 1 < n {
            if arr[i - 1] < arr[i] && arr[i] > arr[i + 1] {
                // expand left
                let mut left = i - 1;
                while left > 0 && arr[left - 1] < arr[left] {
                    left -= 1;
                }
                // expand right
                let mut right = i + 1;
                while right + 1 < n && arr[right] > arr[right + 1] {
                    right += 1;
                }
                let len = right - left + 1;
                if len > max_len {
                    max_len = len;
                }
                // move i to right end to avoid overlapping peaks
                i = right;
            } else {
                i += 1;
            }
        }
        max_len as i32
    }
}

